/** J-07: participants and revocations of a rotated browser session against MariaDB. */
@Tag("mariadb")
@QuarkusTest
@TestProfile(MariaDbFlowProfile.class)
@EnabledIfEnvironmentVariable(named = "V1_MARIADB_URL", matches = ".+")
class SessionLogoutMariaDbTest {
  private final OidcFlowClient client = new OidcFlowClient();
  private static final String TENANT = OidcTestFixtures.TENANT;
  private static final String LOGOUT = "/oauth/openid/" + TENANT + "/logout";

  @Inject
  DataSource dataSource;
  @Inject
  TokenSigner signer;

  private Response login(String clientId, String cookie) {
    var request = RestAssured.given().redirects().follow(false).contentType(ContentType.URLENC)
        .queryParam("client_id", clientId).queryParam("redirect_uri", OidcTestFixtures.REDIRECT_URI)
        .queryParam("response_type", "code").queryParam("scope", OidcTestFixtures.SCOPE)
        .queryParam("nonce", "session-nonce");
    if (cookie != null) {
      request.cookie("AUTH_SESSION_ID", cookie).formParam("csid", OidcTestFixtures.CSID);
    } else {
      request.formParam("username", OidcTestFixtures.USERNAME)
          .formParam("password", OidcTestFixtures.PASSWORD)
          .formParam("csid", OidcTestFixtures.CSID);
    }
    Response response = request.post("/oauth/openid/" + TENANT + "/auth");
    Assertions.assertEquals(302, response.statusCode(), response.asString());
    return response;
  }

  private Response tokens(Response authorize, String clientId) {
    Response result = client.exchangeCodeAsConfidential(TENANT, client.extractAuthCode(authorize),
        OidcTestFixtures.REDIRECT_URI, clientId, OidcTestFixtures.CLIENT_SECRET);
    Assertions.assertEquals(200, result.statusCode(), result.asString());
    return result;
  }

  private Set<String> participants(String cookie) {
    try (Connection connection = dataSource.getConnection();
        PreparedStatement stmt = connection
            .prepareStatement("SELECT client_id FROM _oauth_session_grant WHERE session = ?")) {
      stmt.setString(1, cookie);
      try (ResultSet rows = stmt.executeQuery()) {
        Set<String> result = new HashSet<>();
        while (rows.next())
          result.add(rows.getString(1));
        return result;
      }
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  private boolean revoked(String token) {
    String jti = String.valueOf(signer.verifyTokenPayload(TENANT, token).get("jti"));
    try (Connection connection = dataSource.getConnection();
        PreparedStatement stmt = connection.prepareStatement(
            "SELECT COUNT(*) FROM _oauth_revoked_jti WHERE jti = ? AND tenant_id = ?")) {
      stmt.setString(1, jti);
      stmt.setString(2, TENANT);
      try (ResultSet rows = stmt.executeQuery()) {
        rows.next();
        return rows.getInt(1) > 0;
      }
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  private Response confirm(String cookie) {
    Response get = RestAssured.given().cookie("AUTH_SESSION_ID", cookie).get(LOGOUT);
    Assertions.assertEquals(200, get.statusCode());
    Assertions.assertNotNull(get.getCookie("LOGOUT_CSRF"));
    return get;
  }

  private String sessionState(Response authorization) {
    return java.util.Arrays
        .stream(URI.create(authorization.getHeader("Location")).getRawQuery().split("&"))
        .filter(parameter -> parameter.startsWith("session_state="))
        .map(parameter -> URLDecoder.decode(parameter.substring(14), StandardCharsets.UTF_8))
        .findFirst().orElseThrow();
  }

  private String checkSession(String cookie, String state) {
    return RestAssured.given().cookie("AUTH_SESSION_ID", cookie)
        .queryParam("client_id", OidcTestFixtures.CLIENT_ID)
        .queryParam("origin", "http://localhost").queryParam("session_state", state)
        .get("/oauth/openid/" + TENANT + "/session-check").asString();
  }

  private Response post(String cookie, String csrf, String hint, String redirect) {
    var request = RestAssured.given().redirects().follow(false).contentType(ContentType.URLENC)
        .cookie("AUTH_SESSION_ID", cookie).cookie("LOGOUT_CSRF", csrf).formParam("csrf", csrf)
        .formParam("client_id", OidcTestFixtures.WEB_CLIENT_ID);
    if (hint != null)
      request.formParam("id_token_hint", hint);
    if (redirect != null)
      request.formParam("post_logout_redirect_uri", redirect);
    return request.post(LOGOUT);
  }

  @Test
  void invalidHintOrRedirectCannotEndSessionAndValidPostRevokesOnlyItsOwnGrants() {
    Response first = login(OidcTestFixtures.CLIENT_ID, null);
    String firstCookie = first.getCookie("AUTH_SESSION_ID");
    String firstState = sessionState(first);
    Assertions.assertEquals("unchanged", checkSession(firstCookie, firstState));
    Response firstTokens = tokens(first, OidcTestFixtures.CLIENT_ID);
    Response second = login(OidcTestFixtures.WEB_CLIENT_ID, firstCookie);
    String cookie = second.getCookie("AUTH_SESSION_ID");
    Assertions.assertNotEquals(firstCookie, cookie);
    Assertions.assertEquals("unchanged", checkSession(cookie, firstState));
    Response secondTokens = tokens(second, OidcTestFixtures.WEB_CLIENT_ID);
    Assertions.assertEquals(Set.of(OidcTestFixtures.CLIENT_ID, OidcTestFixtures.WEB_CLIENT_ID),
        participants(cookie));

    Response otherSession = login(OidcTestFixtures.WEB_CLIENT_ID, null);
    Response unrelatedTokens = tokens(otherSession, OidcTestFixtures.WEB_CLIENT_ID);
    String unrelatedToken = unrelatedTokens.jsonPath().getString("access_token");
    String hint = secondTokens.jsonPath().getString("id_token");
    String sid = String.valueOf(signer.verifyTokenPayload(TENANT, hint).get("sid"));
    Assertions.assertNotEquals(cookie, sid);
    Assertions.assertEquals(sid,
        signer.verifyTokenPayload(TENANT, firstTokens.jsonPath().getString("id_token")).get("sid"));

    String csrf = confirm(cookie).getCookie("LOGOUT_CSRF");
    Assertions.assertEquals(403,
        RestAssured.given().contentType(ContentType.URLENC).cookie("AUTH_SESSION_ID", cookie)
            .cookie("LOGOUT_CSRF", csrf).formParam("csrf", "invalid")
            .formParam("client_id", OidcTestFixtures.WEB_CLIENT_ID).formParam("id_token_hint", hint)
            .post(LOGOUT).statusCode());
    Assertions.assertEquals(400, post(cookie, csrf, "invalid.jwt", null).statusCode());
    Assertions.assertEquals(400,
        post(cookie, csrf, firstTokens.jsonPath().getString("id_token"), null).statusCode(),
        "A hint issued to another RP must not close this RP's session");
    Assertions.assertEquals(400,
        post(cookie, csrf, unrelatedTokens.jsonPath().getString("id_token"), null).statusCode(),
        "A hint of another browser session must not close this one");
    Assertions.assertEquals(400,
        post(cookie, csrf, hint, "https://unregistered.example/logout").statusCode());
    Assertions.assertEquals(Set.of(OidcTestFixtures.CLIENT_ID, OidcTestFixtures.WEB_CLIENT_ID),
        participants(cookie), "rejected requests leave the session intact");
    Assertions.assertFalse(revoked(firstTokens.jsonPath().getString("access_token")));

    Response ended = post(cookie, csrf, hint, OidcTestFixtures.POST_LOGOUT_URI);
    Assertions.assertEquals(302, ended.statusCode(), ended.asString());
    Assertions.assertEquals(OidcTestFixtures.POST_LOGOUT_URI, ended.getHeader("Location"));
    Assertions.assertTrue(participants(cookie).isEmpty());
    Assertions.assertEquals("changed", checkSession(cookie, firstState));
    Assertions.assertTrue(revoked(firstTokens.jsonPath().getString("access_token")));
    Assertions.assertTrue(revoked(secondTokens.jsonPath().getString("access_token")));
    Assertions.assertFalse(revoked(unrelatedToken));
  }

  private void notificationClient(String code, String tenantUid, String uri) throws SQLException {
    try (Connection connection = dataSource.getConnection();
        PreparedStatement stmt = connection.prepareStatement("INSERT INTO access_oauth_client"
            + " (uid, version, code, tenant, backchannel_logout_uri, enabled,"
            + " require_pkce, require_pushed_authorization_requests, dpop_bound_access_tokens,"
            + " tls_client_certificate_bound_access_tokens, introspection_allowed, client_credentials_token_ttl_seconds,"
            + " subject_type, token_endpoint_auth_method)"
            + " VALUES (?, 0, ?, ?, ?, 1, 0, 0, 0, 0, 0, 300, 'PUBLIC', 'CLIENT_SECRET_BASIC')")) {
      stmt.setString(1, UUID.randomUUID().toString());
      stmt.setString(2, code);
      stmt.setString(3, tenantUid);
      stmt.setString(4, uri);
      stmt.executeUpdate();
    }
  }

  private String tenant(String name) throws SQLException {
    String uid = UUID.randomUUID().toString();
    try (Connection connection = dataSource.getConnection();
        PreparedStatement stmt = connection.prepareStatement("INSERT INTO access_tenant"
            + " (uid, version, domain, enabled, mark_for_delete, name, root)"
            + " VALUES (?, 0, ?, 1, 0, ?, 0)")) {
      stmt.setString(1, uid);
      stmt.setString(2, name + ".example.invalid");
      stmt.setString(3, name);
      stmt.executeUpdate();
    }
    return uid;
  }

  private void frontClient(String code, String tenantUid, String uri, boolean sidRequired)
      throws SQLException {
    notificationClient(code, tenantUid, "http://127.0.0.1:1/unreachable");
    try (Connection connection = dataSource.getConnection();
        PreparedStatement stmt = connection
            .prepareStatement("UPDATE access_oauth_client SET backchannel_logout_uri = NULL, "
                + "frontchannel_logout_uri = ?, frontchannel_logout_session_required = ? WHERE code = ?")) {
      stmt.setString(1, uri);
      stmt.setBoolean(2, sidRequired);
      stmt.setString(3, code);
      stmt.executeUpdate();
    }
  }

  private void cleanupNotificationFixtures() throws SQLException {
    try (Connection connection = dataSource.getConnection()) {
      try (PreparedStatement clients = connection
          .prepareStatement("DELETE FROM access_oauth_client WHERE code IN (?, ?, ?, ?)")) {
        clients.setString(1, OidcTestFixtures.CLIENT_ID);
        clients.setString(2, OidcTestFixtures.WEB_CLIENT_ID);
        clients.setString(3, OidcTestFixtures.SPA_CLIENT_ID);
        clients.setString(4, "foreign-client");
        clients.executeUpdate();
      }
      try (PreparedStatement tenants =
          connection.prepareStatement("DELETE FROM access_tenant WHERE name IN (?, ?)")) {
        tenants.setString(1, TENANT);
        tenants.setString(2, OidcTestFixtures.OTHER_TENANT);
        tenants.executeUpdate();
      }
    }
  }

  @Test
  void frontChannelRendersOnlyParticipantsAndRedirectsAfterIframes() throws Exception {
    try {
      String ownTenant = tenant(TENANT);
      String otherTenant = tenant(OidcTestFixtures.OTHER_TENANT);
      frontClient(OidcTestFixtures.CLIENT_ID, ownTenant, "http://localhost:9011/first?source=rp",
          true);
      frontClient(OidcTestFixtures.WEB_CLIENT_ID, ownTenant, "http://localhost:9012/second", false);
      frontClient(OidcTestFixtures.SPA_CLIENT_ID, ownTenant,
          "http://localhost:9013/not-participating", true);
      frontClient("foreign-client", otherTenant, "http://localhost:9014/other-tenant", true);

      Response first = login(OidcTestFixtures.CLIENT_ID, null);
      tokens(first, OidcTestFixtures.CLIENT_ID);
      Response second = login(OidcTestFixtures.WEB_CLIENT_ID, first.getCookie("AUTH_SESSION_ID"));
      String cookie = second.getCookie("AUTH_SESSION_ID");
      String hint = tokens(second, OidcTestFixtures.WEB_CLIENT_ID).jsonPath().getString("id_token");
      String sid = String.valueOf(signer.verifyTokenPayload(TENANT, hint).get("sid"));
      String csrf = confirm(cookie).getCookie("LOGOUT_CSRF");
      Response logout = post(cookie, csrf, hint, OidcTestFixtures.POST_LOGOUT_URI);
      Assertions.assertEquals(200, logout.statusCode(), logout.asString());
      String body = logout.asString();
      Assertions.assertEquals(2, body.split("<iframe ", -1).length - 1);
      Assertions.assertTrue(body.contains("first?source=rp&amp;iss="));
      Assertions.assertTrue(body.contains("&amp;sid=" + sid));
      Assertions.assertTrue(body.contains("http://localhost:9012/second"));
      Assertions.assertFalse(body.contains("not-participating"));
      Assertions.assertFalse(body.contains("other-tenant"));
      Assertions.assertFalse(body.contains(cookie));
      Assertions.assertTrue(body.contains("location.replace"));
      Assertions.assertTrue(body.contains(OidcTestFixtures.POST_LOGOUT_URI));
      Assertions.assertTrue(
          logout.getHeader("Content-Security-Policy").contains("http://localhost:9011"));
      Assertions.assertTrue(
          logout.getHeader("Content-Security-Policy").contains("http://localhost:9012"));
      Assertions.assertTrue(participants(cookie).isEmpty());
    } finally {
      cleanupNotificationFixtures();
    }
  }

  @Test
  void backChannelOnlyNotifiesParticipatingClientsWithPublicSid() throws Exception {
    LinkedBlockingQueue<String> notifications = new LinkedBlockingQueue<>();
    HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    server.createContext("/", exchange -> {
      notifications.add(exchange.getRequestURI().getPath() + "?"
          + new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
      exchange.sendResponseHeaders(200, -1);
      exchange.close();
    });
    server.start();
    try {
      String ownTenant = tenant(TENANT);
      String foreignTenant = tenant(OidcTestFixtures.OTHER_TENANT);
      String origin = "http://127.0.0.1:" + server.getAddress().getPort() + "/";
      notificationClient(OidcTestFixtures.CLIENT_ID, ownTenant,
          origin + OidcTestFixtures.CLIENT_ID);
      notificationClient(OidcTestFixtures.WEB_CLIENT_ID, ownTenant,
          origin + OidcTestFixtures.WEB_CLIENT_ID);
      notificationClient(OidcTestFixtures.SPA_CLIENT_ID, ownTenant,
          origin + OidcTestFixtures.SPA_CLIENT_ID);
      notificationClient("foreign-client", foreignTenant, origin + "foreign-client");

      Response first = login(OidcTestFixtures.CLIENT_ID, null);
      tokens(first, OidcTestFixtures.CLIENT_ID);
      Response second = login(OidcTestFixtures.WEB_CLIENT_ID, first.getCookie("AUTH_SESSION_ID"));
      String cookie = second.getCookie("AUTH_SESSION_ID");
      String hint = tokens(second, OidcTestFixtures.WEB_CLIENT_ID).jsonPath().getString("id_token");
      String sid = String.valueOf(signer.verifyTokenPayload(TENANT, hint).get("sid"));
      String csrf = confirm(cookie).getCookie("LOGOUT_CSRF");
      Assertions.assertEquals(200, post(cookie, csrf, hint, null).statusCode());

      Set<String> delivered = new HashSet<>();
      for (int i = 0; i < 2; i++) {
        String message = notifications.poll(5, TimeUnit.SECONDS);
        Assertions.assertNotNull(message, "participant " + i + " should be notified");
        String[] pair = message.split("\\?logout_token=", 2);
        Assertions.assertEquals(2, pair.length);
        String recipient = pair[0].substring(1);
        delivered.add(recipient);
        var jwt = JWT.decode(pair[1]);
        Assertions.assertEquals("logout+jwt", jwt.getType());
        Assertions.assertEquals(sid, jwt.getClaim("sid").asString());
        Assertions.assertNotEquals(cookie, jwt.getClaim("sid").asString());
        Assertions.assertEquals(List.of(recipient), jwt.getAudience());
        Assertions.assertNotNull(jwt.getClaim("events").asMap());
      }
      Assertions.assertEquals(Set.of(OidcTestFixtures.CLIENT_ID, OidcTestFixtures.WEB_CLIENT_ID),
          delivered);
      Assertions.assertNull(notifications.poll(300, TimeUnit.MILLISECONDS));
    } finally {
      server.stop(0);
      cleanupNotificationFixtures();
    }
  }
}
